/** Real TCP/security/browser session and actual owner report beans/native work.
 * Source/settings genesis and global admission are explicit fictional configuration ports; model sender is the original fixture fake. */
class OwnerReportHttpTest {
 @org.springframework.boot.test.context.TestConfiguration(proxyBeanMethods=false)
 @EnableAutoConfiguration(exclude=org.springframework.boot.jdbc.autoconfigure.DataSourceAutoConfiguration.class)
 @Import({ContentController.class,PublicContentRuntimeConfiguration.class,OwnerReportCommandConfiguration.class,BrowserIdentityConfiguration.class,BootstrapSecurityConfiguration.class})
 static class App{}
 static final String ORIGIN="https://site.example.invalid",INTENTS="/admin/reports/generation-intents";
 boolean mysql(){return false;}ReportSupplementPreparationTest h;ConfigurableApplicationContext app;HttpClient client;String root;boolean allowed=true;
 IdentityService.SessionOutcome owner,user;TimeZone previous;
 @BeforeEach void utc(){previous=TimeZone.getDefault();TimeZone.setDefault(TimeZone.getTimeZone("UTC"));}
 void setup(boolean body)throws Exception{
  h=new ReportSupplementPreparationTest(){@Override boolean mysql(){return OwnerReportHttpTest.this.mysql();}};h.setup(body);allowed=true;var base=h.h.h.h.h.f.data.nativeData().fixture().f();
  base.jdbc.execute("DROP TABLE IF EXISTS user_sessions");base.jdbc.execute("DROP TABLE IF EXISTS users");base.jdbc.execute("CREATE TABLE users(id VARCHAR(64) PRIMARY KEY,username VARCHAR(64),password_hash VARCHAR(255))");base.jdbc.execute("CREATE TABLE user_sessions(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64),token_hash BINARY(32),csrf_hash BINARY(32),expires_at TIMESTAMP(6),revoked_at TIMESTAMP(6))");
  String hash=new Argon2Passwords().encode("fictional-long-password");base.jdbc.update("INSERT INTO users VALUES('fictional-owner','fictional-owner',?),('fictional-user','fictional-user',?)",hash,hash);
  var settings=mock(SettingsUpdateService.class);when(settings.freezeForNewInput()).thenAnswer(i->new SettingsUpdateService.Frozen(h.preferences.revision(),h.preferences.followKeywords(),h.preferences.blockedKeywords(),null));var gate=mock(OperationalInputGate.class);when(gate.preparationAllowed()).thenAnswer(i->allowed);
  app=new SpringApplicationBuilder(App.class).properties("server.port=0","server.address=127.0.0.1","spring.main.banner-mode=off","logging.level.root=ERROR").initializers(c->{var registry=(GenericApplicationContext)c;registry.registerBean(javax.sql.DataSource.class,()->base.source);registry.registerBean(org.springframework.transaction.PlatformTransactionManager.class,()->base.tx);registry.registerBean(ReportPreparedInputService.class,()->h.originals);registry.registerBean(ReportInputWriterAdmissionService.class,()->h.admission);registry.registerBean(SettingsUpdateService.class,()->settings);registry.registerBean(OperationalInputGate.class,()->gate);}).run("--site.browser.enabled=true","--site.content.enabled=true","--site.articles.enabled=true","--site.sources.enabled=true","--site.execution.enabled=true","--site.collector.enabled=true","--site.sources.day-roster.enabled=true","--site.execution.report-preparation.enabled=true","--SITE_BROWSER_ORIGIN="+ORIGIN,"--SITE_OWNER_IDS=fictional-owner","--SITE_USER_IDS=fictional-user");
  root="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();client=HttpClient.newHttpClient();owner=login("fictional-owner");user=login("fictional-user");
 }
 IdentityService.SessionOutcome login(String name){var browser=app.getBean(BrowserSessionService.class);var challenge=browser.session(null,null);return browser.login(new IdentityService.LoginCommand(name,"fictional-long-password"),null,challenge.anonymousToken(),challenge.session().csrfToken(),ORIGIN);}
 @AfterEach void close(){try{if(client!=null)client.close();if(app!=null)app.close();}finally{TimeZone.setDefault(previous);}}
 HttpResponse<String> post(String path,String body,String key,IdentityService.SessionOutcome session,String csrf,String origin)throws Exception{var request=HttpRequest.newBuilder(URI.create(root+path)).timeout(Duration.ofSeconds(20)).header("Content-Type","application/json");if(session!=null)request.header("Cookie","lianxibu_session="+session.sessionToken());if(csrf!=null)request.header("X-CSRF-Token",csrf);if(origin!=null)request.header("Origin",origin);if(key!=null)request.header("Idempotency-Key",key);return client.send(request.POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 HttpResponse<String> post(String path,String body,String key)throws Exception{return post(path,body,key,owner,owner.session().csrfToken(),ORIGIN);}
 String intent(LocalDate day,String mode,Long revision){var zone=ZoneId.of("Asia/Shanghai");var format=new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter();var node=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("kind","daily").put("period_start",format.format(day.atStartOfDay(zone).toInstant())).put("period_end",format.format(day.plusDays(1).atStartOfDay(zone).toInstant())).put("timezone","Asia/Shanghai").put("mode",mode).put("reason",h.command.reason());if(revision!=null)node.put("intent_revision",revision);return JdbcFrozenInputs.canonical(node);}
 tools.jackson.databind.JsonNode data(HttpResponse<String> response,int status){assertEquals(status,response.statusCode(),response.body());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());return CanonicalJson.parse(response.body()).get("data");}
 String action(){return "{\"expected_revision\":1,\"action\":\"supplement_generate\",\"reason\":\""+h.command.reason()+"\"}";}
 @Test void InitialActualHttpCreatesOnlyStableIntentAndOriginalReplaySurvivesPause()throws Exception{setup(true);var base=h.h.h.h.h.f.data.nativeData().fixture().f();var day=LocalDate.parse("2026-02-01");var before=base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Long.class);String body=intent(day,"initial",null);var first=data(post(INTENTS,body,"fictional-http-initial"),202);assertEquals("waiting_input",first.get("state").asString());assertEquals("partial",first.get("coverage").get("state").asString());assertEquals(0,first.get("call_count").asInt());assertTrue(first.get("max_attempts").isNull());allowed=false;base.jdbc.update("UPDATE worker_lock SET slot_revision=slot_revision+1");assertEquals(first,data(post(INTENTS,body,"fictional-http-initial"),202));assertEquals(before,base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Long.class));assertEquals(409,post(INTENTS,body.replace(h.command.reason(),"Fictional changed reason"),"fictional-http-initial").statusCode());assertEquals(1,h.h.reportSends);}
 @Test void ExistingReportSupplementCommitsSecondIntentWithoutChangingBodyAndHasPermanentReplay()throws Exception{setup(true);var base=h.h.h.h.h.f.data.nativeData().fixture().f();String path="/admin/content/report/"+h.id+"/actions";String old=base.jdbc.queryForObject("SELECT body_json FROM contents WHERE id=?",String.class,h.id);var first=data(post(path,action(),"fictional-http-action"),200);assertEquals(2,first.get("generation").asInt());assertEquals(1,first.get("result_revision").asInt());assertEquals(old,base.jdbc.queryForObject("SELECT body_json FROM contents WHERE id=?",String.class,h.id));base.jdbc.update("UPDATE contents SET revision=revision+1 WHERE id=?",h.id);allowed=false;assertEquals(first,data(post(path,action(),"fictional-http-action"),200));assertEquals(409,post(path,action().replace(h.command.reason(),"Fictional changed reason"),"fictional-http-action").statusCode());assertEquals(1,h.h.reportSends);assertEquals(0,new JdbcJobRecords(base.source).byId(h.nextRoot()).callCount());}
 @Test void AbsentContentSupplementEndpointCreatesRealSecondIntentAndRejectsStaleIntentCas()throws Exception{setup(false);var base=h.h.h.h.h.f.data.nativeData().fixture().f();String body=intent(h.command.scope().day(),"supplement",0L);var first=data(post(INTENTS,body,"fictional-http-absent"),202);assertEquals(1,first.get("intent_revision").asInt());assertEquals(0L,base.jdbc.queryForObject("SELECT COUNT(*) FROM contents WHERE id=?",Long.class,h.id));assertNotNull(new JdbcJobRecords(base.source).byId(h.nextRoot()));allowed=false;assertEquals(first,data(post(INTENTS,body,"fictional-http-absent"),202));allowed=true;assertEquals(409,post(INTENTS,body,"fictional-http-stale").statusCode());assertNull(new JdbcJobRecords(base.source).byId(JdbcReportPreparedInputs.root(h.command.scope().logicalKey(),3)));assertEquals(1,h.h.reportSends);}
 @Test void ActualSessionsCsrfOriginClosedFieldsAndSqlFailureRemainRejectedAndSanitized()throws Exception{setup(true);var base=h.h.h.h.h.f.data.nativeData().fixture().f();String body=intent(LocalDate.parse("2026-02-01"),"initial",null);var before=base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class);assertEquals(401,post(INTENTS,body,"fictional-http-no-session",null,null,null).statusCode());assertEquals(403,post(INTENTS,body,"fictional-http-user",user,user.session().csrfToken(),ORIGIN).statusCode());assertEquals(403,post(INTENTS,body,"fictional-http-csrf",owner,"wrong",ORIGIN).statusCode());assertEquals(403,post(INTENTS,body,"fictional-http-origin",owner,owner.session().csrfToken(),"https://other.example.invalid").statusCode());assertEquals(422,post(INTENTS,body,null).statusCode());assertEquals(400,post(INTENTS,body.substring(0,body.length()-1)+",\"intent_revision\":0}","fictional-http-extra").statusCode());assertEquals(before,base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));base.jdbc.execute("DROP TABLE jobs");var failed=post(INTENTS,body,"fictional-http-sql");assertEquals(503,failed.statusCode(),failed.body());assertFalse(failed.body().contains("SELECT"));assertFalse(failed.body().contains("INSERT"));assertEquals("temporarily_unavailable",CanonicalJson.parse(failed.body()).at("/error/code").asString());assertEquals(1,h.h.reportSends);}
}
